const withoutId = <T extends { id?: string }>(value: T) => { const { id: _id, ...record } = value; return record; };
const withId = <T extends object>(id: string, value: T): T & { id: string } => ({ ...value, id });
const bodyOf = (body: unknown) => body && typeof body === 'object' ? body as Record<string, unknown> : {};
/**
 * Elke lijst uit app.records. Draagt de vraag een `ownerUserId`, dan hoort er een LADE bij: de filter krijgt
 * `ruimte` mee (ladeFilter) en het resultaat wordt nagerekend met `hoortBij` — nodig omdat de persoonlijke lade ook
 * de rijen ZONDER `ruimte` moet vinden (alles van vóór migratie 0084), wat een jsonb-filter niet kan uitdrukken.
 * Vragen zonder eigenaar (de serverrij app.records/provider_endpoint_verifications_v1) blijven precies zoals ze waren.
 */
const rows = async <T extends object>(table: string, filter: Record<string, unknown>) => {
  const eigenaar = typeof filter.ownerUserId === 'string' ? filter.ownerUserId : '';
  if (!eigenaar) return (await db.list<T>(table, { filter })).items as Array<T & { id: string }>;
  const lade = ladeOf(eigenaar);
  const items = (await db.list<T>(table, { filter: { ...filter, ...ladeFilter(lade) } })).items as Array<T & { id: string }>;
  return items.filter(item => hoortBij(item as Record<string, unknown>, lade));
};
const latest = async <T extends object>(table: string, filter: Record<string, unknown>) => (await rows<T>(table, filter)).sort((a, b) => Number((b as Record<string, unknown>).updatedAt || (b as Record<string, unknown>).createdAt || 0) - Number((a as Record<string, unknown>).updatedAt || (a as Record<string, unknown>).createdAt || 0))[0] || null;
