const key = (secret: string) => createHash('sha256').update(secret, 'utf8').digest();
const aad = (ownerUserId: string, principalId: string, providerAccountId: string) => Buffer.from(`google-oauth-grant-v1|${ownerUserId}|${principalId}|${providerAccountId}|${CLIENT_REF}`, 'utf8');
/* Sleutelkluis (0092): keyVersion 1 = serversleutel (GOOGLE_OAUTH_GRANT_ENCRYPTION_KEY_V1), keyVersion 2 = de EIGEN gegevenssleutel van de mens (DEK, open vereist). Staat de kluis aan, dan wordt NOOIT meer met de serversleutel geschreven; oude rijen (v1) blijven leesbaar en worden geteld; «перешифрувати зараз» zet ze om (herversleutelaar onderaan). De lade komt uit de lopende aanroep (ladeOf) — buiten een bewaakte route de persoonlijke. */
const grantLade = (ownerUserId: string) => { const l = ladeOf(ownerUserId); return { userId: ownerUserId, ruimte: ruimteOf(l.ruimte) }; };
const encryptGrantServer = (plaintext: string, secret: string, context: { ownerUserId: string; principalId: string; providerAccountId: string }): GrantEnvelope => { if (secret.length < 32) throw new Error('GOOGLE_OAUTH_GRANT_ENCRYPTION_KEY_WEAK'); const iv = randomBytes(12), cipher = createCipheriv('aes-256-gcm', key(secret), iv); cipher.setAAD(aad(context.ownerUserId, context.principalId, context.providerAccountId)); const ciphertext = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]); return { algorithm: 'AES-256-GCM', keyVersion: 1, ciphertext: ciphertext.toString('base64'), iv: iv.toString('base64'), authTag: cipher.getAuthTag().toString('base64') }; };
const encryptGrantDek = (dek: Buffer, plaintext: string, context: { ownerUserId: string; principalId: string; providerAccountId: string }): GrantEnvelope => { const iv = randomBytes(12), cipher = createCipheriv('aes-256-gcm', dek, iv); cipher.setAAD(aad(context.ownerUserId, context.principalId, context.providerAccountId)); const ciphertext = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]); return { algorithm: 'AES-256-GCM', keyVersion: 2 as unknown as 1, ciphertext: ciphertext.toString('base64'), iv: iv.toString('base64'), authTag: cipher.getAuthTag().toString('base64') }; };
const encryptGrant = async (plaintext: string, secret: string, context: { ownerUserId: string; principalId: string; providerAccountId: string }): Promise<GrantEnvelope> => { const lade = grantLade(context.ownerUserId); if (await kluisIngeschakeld(lade)) { const dek = sleutelOpen(lade); if (!dek) throw new Error(SLEUTEL_GESLOTEN_CODE); return encryptGrantDek(dek, plaintext, context); } return encryptGrantServer(plaintext, secret, context); };
