export const createGoogleSuiteOnboardingRoutes = (authorize: CloudAuthorize) => ({
  'POST /api/owner/cloud/google-suite/onboarding/status': [async (ctx: CloudContext) => { const auth = await cloudAuth(authorize, ctx); if (!auth) return error('OWNER_CLOUD_SESSION_REQUIRED', 403); return json(await googleSuiteOnboardingSnapshot(auth.user.id, auth.user.email)); }],
  'POST /api/owner/cloud/google-suite/onboarding/verify': [async (ctx: CloudContext) => { const auth = await cloudAuth(authorize, ctx); if (!auth) return error('OWNER_CLOUD_SESSION_REQUIRED', 403); const service = safeText(bodyOf(ctx.body).service, 30) as PlanService; if (!PLAN.includes(service)) return error('GOOGLE_SUITE_SERVICE_INVALID', 400); return json({ platform: await servicePlatform(service, true), selfTests: googleSuitePolicySelfTest() }); }],
  'POST /api/owner/cloud/google-suite/drive/preview': [async (ctx: CloudContext) => { const auth = await cloudAuth(authorize, ctx); if (!auth) return error('OWNER_CLOUD_SESSION_REQUIRED', 403); try { return json(await googleSuiteDrivePreview(auth.user.id, auth.user.email)); } catch { return error('GOOGLE_SUITE_DRIVE_PREVIEW_UNAVAILABLE', 409); } }],
  'POST /api/owner/cloud/google-suite/onboarding/start': [async (ctx: CloudContext) => { const auth = await cloudAuth(authorize, ctx); if (!auth) return error('OWNER_CLOUD_SESSION_REQUIRED', 403); const body = bodyOf(ctx.body), service = safeText(body.suiteService, 30) as PlanService; if (!PLAN.includes(service)) return error('GOOGLE_SUITE_SERVICE_INVALID', 400); return startConsent(auth, body, service, 'primary'); }]
});

// Sleutelkluis (0092): oude Google-refresh-tokens (keyVersion 1, serversleutel) van déze lade onder de DEK (keyVersion 2) zetten.
registreerHerversleutelaar(OAUTH_GRANTS, (lade, dek) => metLade({ userId: lade.userId, ruimte: lade.ruimte }, 'cloud', async () => {
  const alle = await rows<Omit<OAuthGrant, 'id'>>(OAUTH_GRANTS, { ownerUserId: lade.userId, provider: 'google', tokenKind: 'refresh_token' });
  const grants = (alle as OAuthGrant[]).filter((g) => hoortBij(g as unknown as Record<string, unknown>, lade) && Number(g.keyVersion) !== 2 && g.grantStatus !== 'revoked');
  if (!grants.length) return { gevonden: 0, herversleuteld: 0 };
  const secret = await secrets.readSecret(GRANT_KEY_SECRET);
  let herversleuteld = 0;
  for (const g of grants) {
    try {
      const [principal] = await db.get<Omit<Principal, 'id'>>(PRINCIPALS, [g.principalId]);
      if (!principal) continue;
      const context = { ownerUserId: lade.userId, principalId: g.principalId, providerAccountId: principal.providerAccountId };
      const refresh = decryptGrantMet(key(secret), g, context);
      const envelope = encryptGrantDek(dek, refresh, context);
      await db.update(OAUTH_GRANTS, [{ id: g.id, record: withoutId({ ...g, ...envelope, updatedAt: Date.now() }) }]);
      herversleuteld++;
    } catch { /* blijft keyVersion 1; de teller zegt het */ }
  }
  return { gevonden: grants.length, herversleuteld };
}));
